// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const item = $input.first().json;
const text = item.message?.text || '';
const msg = text.toLowerCase().trim();
const sid = String(item.message?.chat?.id);

const store = $getWorkflowStaticData('global');
store.routes = store.routes || {};
store.runs = store.runs || {};

if (msg.startsWith('/start')) {
  delete store.routes[sid];
  store.runs[sid] = (store.runs[sid] || 0) + 1;
} else if (msg.length <= 40) {
  const current = store.routes[sid];
  if (/^improve/.test(msg) || (!current && msg === '2')) store.routes[sid] = 'improve_cv';
  else if (/^(find )?opportunit/.test(msg) || (!current && msg === '3')) store.routes[sid] = 'job_targeting';
  else if (/^(create|new cv)/.test(msg) || (!current && msg === '1')) store.routes[sid] = 'create_cv';
}

return [{ json: {
  chatInput: text,
  sessionId: sid,
  memKey: sid + '_' + (store.runs[sid] || 0),
  route: store.routes[sid] || 'unknown'
} }];
